cd /home/ubuntu/.agent-ml-research-be-idea-gen-0519-4/projects/policy_ambiguity_safety && python3 -c "
import json
# Check clause_id patterns per type
models = ['gpt-5.4', 'gpt-4.1', 'claude-sonnet-4-6', 'deepseek-v3', 'qwen3-235b']
for m in models[:1]:
    with open(f'artifacts/full_study/judgments/{m}/judgments.jsonl') as f:
        lines = [json.loads(l) for l in f]
    types = {}
    for l in lines:
        t = l['ambiguity_type']
        c = l['condition']
        types.setdefault(t, {}).setdefault(c, set()).add(l['clause_id'])
    for t, conds in sorted(types.items()):
        for c, ids in sorted(conds.items()):
            print(f'{m} | {t} | {c} | {len(ids)} clauses | e.g. {sorted(ids)[:3]}')
"

